{
  "decision-book-drop-pilot-paired-stops": "WITH usable AS (SELECT stop_code, phase_name, source_id, unload_seconds, crate_count FROM stop_report WHERE phase_name IN ('before', 'pilot') AND unload_seconds IS NOT NULL AND crate_count > 0), pooled AS (SELECT stop_code, phase_name, SUM(unload_seconds) AS pooled_seconds, SUM(crate_count) AS pooled_crates FROM usable GROUP BY stop_code, phase_name), qualifying AS (SELECT b.stop_code FROM pooled AS b JOIN pooled AS p ON p.stop_code = b.stop_code WHERE b.phase_name = 'before' AND p.phase_name = 'pilot' AND p.pooled_seconds * b.pooled_crates < b.pooled_seconds * p.pooled_crates) SELECT u.stop_code, u.phase_name, u.source_id, t.pooled_seconds, t.pooled_crates FROM usable AS u JOIN qualifying AS q ON q.stop_code = u.stop_code JOIN pooled AS t ON t.stop_code = u.stop_code AND t.phase_name = u.phase_name ORDER BY u.stop_code COLLATE BINARY, CASE u.phase_name WHEN 'before' THEN 0 ELSE 1 END, u.source_id COLLATE BINARY",
  "decision-book-nonoverlapping-shaker-visits": "WITH bookings AS (SELECT block_code AS first_block, NULL AS second_block, ready_bins AS filled_bins FROM shaker_offer UNION ALL SELECT a.block_code, b.block_code, a.ready_bins + b.ready_bins FROM shaker_offer AS a JOIN shaker_offer AS b ON a.finish_min <= b.start_min) SELECT b.first_block, b.second_block, b.filled_bins, c.card_id FROM bookings AS b CROSS JOIN dispatch_card AS c WHERE b.filled_bins <= c.bin_limit ORDER BY b.filled_bins DESC, (b.second_block IS NOT NULL), b.first_block COLLATE BINARY, b.second_block COLLATE BINARY LIMIT 1",
  "decision-book-uninterrupted-tug-charge": "SELECT t.source_id, a.hour_no AS start_hour, t.draw_kw * (a.price_cents + b.price_cents) AS cost_cents FROM feeder_quote AS a JOIN feeder_quote AS b ON b.hour_no = a.hour_no + 1 CROSS JOIN tug_order AS t WHERE a.hour_no / 24 = b.hour_no / 24 AND a.spare_kw >= t.draw_kw AND b.spare_kw >= t.draw_kw ORDER BY cost_cents, start_hour LIMIT 1",
  "decision-bound-cartons-needing-rework": "WITH ordered AS (SELECT shipment_code, source_id, CASE WHEN both_qty IS NULL THEN MAX(corner_qty, label_qty) ELSE (corner_qty - both_qty) + label_qty END AS lo, CASE WHEN both_qty IS NULL THEN corner_qty + MIN(label_qty, carton_qty - corner_qty) ELSE (corner_qty - both_qty) + label_qty END AS hi FROM pallet_cert ORDER BY shipment_code COLLATE BINARY, source_id COLLATE BINARY) SELECT shipment_code, SUM(lo) AS min_cartons, SUM(hi) AS max_cartons, GROUP_CONCAT(source_id, ',') AS evidence_ids FROM ordered GROUP BY shipment_code COLLATE BINARY ORDER BY shipment_code COLLATE BINARY"
}
